entries[446985] = { ["name"] = "Magically \"Infinite\" Messenger", ["text"] = "2 sec cast 2\nReagents:\nOptional Reagents:\nEmbroidery Thread (#333)\nVendor:\nIliani\nZone:\nCity of Threads\nCost:\n150\n1500\n\nVendor:\nVenomscribe Xesh XI\nZone:\nCity of Threads\nCost:\n150\n1500\n\nMagically \"Infinite\" Messenger\nBinds when picked up\nUnique\n36 Slot Bag\nEquip: The amount of Resourcefulness, Ingenuity, and Multicraft provided by Shatter Essence is increased by 20.\n\n[ Equip effect requires Khaz Algar Enchanting 1 ][ Equip effect requires Khaz Algar Enchanting 1 ]68\n\"Rumors of its infiniteness have been greatly exaggerated.\"" }
