entries[446996] = { ["name"] = "Bright Polishing Cloth", ["text"] = "2 sec cast\nReagents:\nLeyline Residue (2), Weavercloth Bolt\nOptional Reagents:\nProfession Trainer:\nKhaz Algar Tailoring (40)\nCost:\n210\n\nBright Polishing Cloth\nFinishing Crafting Reagent\n\nWhen crafting: Multicraft yields 25% more when crafting consumable items.\nUsable with: Most Khaz Algar Jewelcrafting recipes.\n\"Can be bought and sold on the Auction House.\"" }
entries[446997] = { ["name"] = "Weavercloth Embroidery Thread", ["text"] = "2 sec cast\nReagents:\nWrithing Sample , Weavercloth Bolt\nOptional Reagents:\nProfession Trainer:\nKhaz Algar Tailoring (45)\nCost:\n240\n\nWeavercloth Embroidery Thread\nFinishing Crafting Reagent\n\nWhen crafting: Increases Ingenuity by 300.\nUsable with: Most Khaz Algar Tailoring recipes.\n\"Can be bought and sold on the Auction House.\"" }
