entries[446999] = { ["name"] = "Weavercloth Spellthread", ["text"] = "2 sec cast\nReagents:\nAdorning Ribbon (3), Exquisite Weavercloth Bolt (8)\nOptional Reagents:\nSpecialization:\nQuality Fabric - Spellthread\n\nWeavercloth Spellthread\n\nUse: Apply Weavercloth Spellthread to your leggings, permanently increasing its Intellect by 4.\n70\nCrafting Reagent" }
